func activityIcon(kind string) string {
	switch kind {
	case "lead.created":
		return "plus"
	case "lead.enriched":
		return "zap"
	case "lead.qualified":
		return "flame"
	case "email.sent", "reply.received":
		return "mail"
	case "task.created":
		return "check-square"
	case "deal.created", "deal.stage_changed", "deal.won":
		return "handshake"
	default:
		return "activity"
	}
}

